function decisionMetrics(state,end){
 const dates=Array.from({length:7},(_,i)=>shift(end,-i)),previous=dates.map(d=>shift(d,-7));
 const weightMean=days=>{const daily=days.map(day=>state.measurements.filter(m=>m.date===day&&!m.reviewRequired).map(m=>m.weight)).filter(a=>a.length).map(a=>a.reduce((s,v)=>s+v,0)/a.length);return {days:daily.length,value:daily.length?daily.reduce((s,v)=>s+v,0)/daily.length:null}};
 const weight=weightMean(dates),before=weightMean(previous);
 const complete=dates.filter(d=>state.nutrition.completedDays?.[d]===true);
 const daily=complete.map(d=>state.meals.filter(m=>m.date===d).reduce((s,m)=>({calories:s.calories+m.calories,protein:s.protein+m.protein}),{calories:0,protein:0}));
 const mean=k=>daily.length?daily.reduce((s,d)=>s+d[k],0)/daily.length:null;
 const workouts=state.workouts.filter(w=>dates.includes(w.date)),groups={};
 for(const w of workouts)if(w.exerciseType!=='كارديو')groups[w.group]=(groups[w.group]||0)+w.sets.length;
 const plan=state.training.exercises||[],sessions=['1','2','3','4'].filter(s=>plan.some(x=>x.session===s));
 const finished=s=>dates.some(date=>plan.filter(x=>x.session===s).every(x=>state.training[date+':'+x.id]===true));
 const next=sessions.find(s=>!finished(s));
 return {weight,before,complete:complete.length,calories:mean('calories'),protein:mean('protein'),workoutDays:new Set(workouts.map(w=>w.date)).size,groups,next,sessionCount:sessions.length,finished:sessions.filter(finished).length};
}
function decisionPanel(){const m=decisionMetrics(data,selected),target=data.targets,hasWeight=m.weight.days>=3&&m.before.days>=3;return `<div class="card"><div class="card-head"><div><h2>مراجعة أسبوعك</h2><p class="sub">${pretty(shift(selected,-6))} — ${pretty(selected)}</p></div><a class="button secondary" href="#meals">مراجعة التغذية</a></div><div class="mini-grid"><div class="mini"><small>أيام غذائية مكتملة</small><strong>${m.complete} / 7</strong></div><div class="mini"><small>أيام تمرين مسجلة</small><strong>${m.workoutDays}${target.workoutDays?' / '+target.workoutDays:''}</strong></div><div class="mini"><small>جلسات الخطة المكتملة</small><strong>${m.finished} / ${m.sessionCount}</strong></div></div><h3>اتجاه الوزن</h3><p>${hasWeight?`متوسط الأسبوع ${fmt(m.weight.value)} كجم مقابل ${fmt(m.before.value)} كجم للأسبوع السابق؛ الفرق ${fmt(m.weight.value-m.before.value)} كجم. هذا تغير في الوزن، وليس قياسًا مباشرًا لتغير الدهون.`:`المقارنة تحتاج قياسات في ٣ أيام مختلفة على الأقل لكل أسبوع. المتوفر: ${m.weight.days} أيام هذا الأسبوع و${m.before.days} في السابق.`}</p><h3>قرار التغذية</h3><p>${m.complete?`متوسط الأيام التي أكدت اكتمالها: ${fmt(m.calories)} سعرة و${fmt(m.protein)} غ بروتين.${target.calories?' فرق متوسط السعرات عن هدفك: '+fmt(m.calories-target.calories)+' سعرة.':''}${target.protein?' فرق متوسط البروتين عن هدفك: '+fmt(m.protein-target.protein)+' غ.':''} ${m.complete<4?'السجل غير مكتمل لمعظم الأسبوع؛ أكمل التسجيل قبل تقييم ملاءمة الهدف.':'راجع هذا الملخص مع اتجاه الوزن ونشاطك قبل تعديل هدفك.'}`:'أكد اكتمال تسجيل وجبات اليوم من قسم التغذية لبدء المقارنة. الأيام الناقصة لا تُحسب على أنها صفر.'}</p><h3>قرار التمرين</h3><p>${!m.sessionCount?'أضف خطة تمارين لتتبع الجلسات المتبقية.':m.next?`الجلسة ${m.next} هي أول جلسة لم تُستكمل في آخر ٧ أيام. افتحها لمراجعة التمارين؛ هذا ترتيب للخطة وليس تقييمًا لجاهزيتك البدنية.`:'أكملت جميع جلسات الخطة خلال آخر ٧ أيام.'}</p><div class="quick-buttons">${m.next?`<button class="button" data-next-session="${m.next}">فتح الجلسة ${m.next}</button>`:'<a class="button secondary" href="#workouts">برنامج التمارين</a>'}<button class="button secondary" data-feature="intake">مراجعة الهدف الغذائي</button></div>${Object.keys(m.groups).length?`<h3>الجولات الفعلية حسب المجموعة</h3><div class="chips">${Object.entries(m.groups).map(([g,n])=>`<span class="chip">${esc(g)}: ${n} جولة</span>`).join('')}</div>`:''}<p class="sub">لا نرفع الأوزان أو نغيّر السعرات تلقائيًا من قراءة واحدة. راجع الأداء والتعافي ودقة السجل أولًا.</p></div>`}
const nutritionTabs=plan=>`<div class="quick-buttons" style="margin-bottom:20px"><a class="button ${plan?'secondary':''}" href="#meals" ${!plan?'aria-current="page"':''}>ما أكلته</a><a class="button ${plan?'':'secondary'}" href="#nutrition" ${plan?'aria-current="page"':''}>الخطة المقترحة</a><a class="button secondary" href="#progress">مراجعة أسبوعي</a></div>`;
const mealsBeforeInsights=renderMeals;renderMeals=()=>nutritionTabs(false)+`<div class="card"><div class="card-head"><div><h2>اكتمال سجل ${pretty(selected)}</h2><p class="sub">أكّد بعد تسجيل جميع الوجبات والمشروبات ذات السعرات. يمكنك إلغاء التأكيد في أي وقت.</p></div><button class="button ${data.nutrition.completedDays?.[selected]?'secondary':''}" data-meal-day>${data.nutrition.completedDays?.[selected]?'إلغاء اكتمال اليوم':'اكتمل تسجيل يومي'}</button></div></div>`+mealsBeforeInsights();
const planBeforeInsights=window.renderNutritionPlan;window.renderNutritionPlan=()=>nutritionTabs(true)+planBeforeInsights();
const progressBeforeInsights=renderProgress;renderProgress=()=>decisionPanel()+progressBeforeInsights();
const todayBeforeInsights=renderToday;renderToday=()=>`<div class="card"><div class="card-head"><div><h2>قراراتك مبنية على تقدمك</h2><p class="sub">راجع اتجاه الوزن والتغذية والجلسات المتبقية قبل تغيير خطتك.</p></div><a class="button secondary" href="#progress">مراجعة أسبوعي</a></div></div>`+todayBeforeInsights();
document.addEventListener('click',e=>{if(e.target.closest('[data-meal-day]')){const next=structuredClone(data);next.nutrition.completedDays={...next.nutrition.completedDays,[selected]:!next.nutrition.completedDays?.[selected]};commit(next,'تم تحديث اكتمال اليوم')}const session=e.target.closest('[data-next-session]')?.dataset.nextSession;if(session){trainingSession=session;location.hash='workouts';view='workouts';render()}});
render();
